content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: light dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #121212;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  display: flex;
  place-content: center;
  min-width: 320px;
  min-height: 100vh;
  background: #0f172a;
  color: #f8fafc;
}

#root {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem;
}

.app-container {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
  padding: 1rem;
}

.header {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.title {
  font-size: 2.25rem;
  font-weight: 800;
  background: linear-gradient(135deg, #38bdf8 0%, #818cf8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  font-size: 1rem;
  color: #94a3b8;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #1e293b;
  border-radius: 1rem;
  overflow: hidden;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
  border: 1px solid #334155;
  cursor: crosshair;
}

.simulation-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  background: #1e293b;
  padding: 1.5rem;
  border-radius: 1rem;
  border: 1px solid #334155;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  align-items: center;
  justify-content: space-between;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex: 1;
  min-width: 200px;
}

.control-group label {
  font-size: 0.875rem;
  font-weight: 500;
  color: #cbd5e1;
  display: flex;
  justify-content: space-between;
}

.control-group input[type="range"] {
  width: 100%;
  accent-color: #38bdf8;
  cursor: pointer;
}

.button-group {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 0.5rem;
  border: 1px solid #475569;
  background-color: #334155;
  color: #f8fafc;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.btn:hover {
  background-color: #475569;
  border-color: #64748b;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: #0284c7;
  border-color: #0369a1;
  color: #ffffff;
}

.btn-primary:hover {
  background-color: #0ea5e9;
  border-color: #0284c7;
}

.stats {
  display: flex;
  justify-content: space-around;
  background: #1e293b;
  padding: 1rem;
  border-radius: 0.75rem;
  border: 1px solid #334155;
  font-size: 0.875rem;
  color: #94a3b8;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
}

.stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: #f8fafc;
}

@media (max-width: 640px) {
  .controls {
    flex-direction: column;
    align-items: stretch;
  }

  .button-group {
    width: 100%;
    justify-content: stretch;
  }

  .button-group .btn {
    flex: 1;
  }
}

export interface Ball {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
}

export interface SimulationSettings {
  gravity: number;
  restitution: number;
  friction: number;
}

import { SimulationSettings } from '../types';

interface ControlPanelProps {
  settings: SimulationSettings;
  onUpdateSettings: (settings: SimulationSettings) => void;
  onReset: () => void;
  onAddBall: () => void;
  ballCount: number;
}

export default function ControlPanel({
  settings,
  onUpdateSettings,
  onReset,
  onAddBall,
}: ControlPanelProps) {
  const handleChange = (key: keyof SimulationSettings, value: number) => {
    onUpdateSettings({
      ...settings,
      [key]: value,
    });
  };

  return (
    <div className="controls">
      <div className="control-group">
        <label>
          重力 <span>{settings.gravity.toFixed(1)}</span>
        </label>
        <input
          type="range"
          min="0"
          max="2"
          step="0.1"
          value={settings.gravity}
          onChange={(e) => handleChange('gravity', parseFloat(e.target.value))}
        />
      </div>

      <div className="control-group">
        <label>
          反発係数 <span>{settings.restitution.toFixed(2)}</span>
        </label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.05"
          value={settings.restitution}
          onChange={(e) => handleChange('restitution', parseFloat(e.target.value))}
        />
      </div>

      <div className="control-group">
        <label>
          空気抵抗 <span>{settings.friction.toFixed(3)}</span>
        </label>
        <input
          type="range"
          min="0.95"
          max="1"
          step="0.001"
          value={settings.friction}
          onChange={(e) => handleChange('friction', parseFloat(e.target.value))}
        />
      </div>

      <div className="button-group">
        <button className="btn btn-primary" onClick={onAddBall}>
          ボール追加
        </button>
        <button className="btn" onClick={onReset}>
          リセット
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { Ball, SimulationSettings } from './types';
import ControlPanel from './components/ControlPanel';

const COLORS = ['#38bdf8', '#818cf8', '#f472b6', '#34d399', '#fbbf24', '#f87171'];

export default function App() {
  const [settings, setSettings] = useState<SimulationSettings>({
    gravity: 0.5,
    restitution: 0.8,
    friction: 0.99,
  });

  const [balls, setBalls] = useState<Ball[]>(() => {
    return Array.from({ length: 5 }, (_, i) => ({
      id: i,
      x: 100 + i * 120,
      y: 100 + (i % 2) * 50,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      radius: 20 + Math.random() * 15,
      color: COLORS[i % COLORS.length],
    }));
  });

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[]>(balls);
  ballsRef.current = balls;
  const settingsRef = useRef<SimulationSettings>(settings);
  settingsRef.current = settings;

  const addBallAt = useCallback((x: number, y: number) => {
    const newBall: Ball = {
      id: Date.now() + Math.random(),
      x,
      y,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      radius: 15 + Math.random() * 20,
      color: COLORS[Math.floor(Math.random() * COLORS.length)],
    };
    setBalls((prev) => [...prev, newBall]);
  }, []);

  const handleAddBall = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    addBallAt(canvas.width / 2 + (Math.random() - 0.5) * 100, 50);
  };

  const handleReset = () => {
    setBalls(
      Array.from({ length: 5 }, (_, i) => ({
        id: i,
        x: 100 + i * 120,
        y: 100 + (i % 2) * 50,
        vx: (Math.random() - 0.5) * 6,
        vy: (Math.random() - 0.5) * 6,
        radius: 20 + Math.random() * 15,
        color: COLORS[i % COLORS.length],
      }))
    );
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    addBallAt(x, y);
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const render = () => {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const currentSettings = settingsRef.current;
      const updatedBalls = ballsRef.current.map((ball) => {
        let { x, y, vx, vy, radius } = ball;

        vy += currentSettings.gravity;
        vx *= currentSettings.friction;
        vy *= currentSettings.friction;

        x += vx;
        y += vy;

        if (x - radius < 0) {
          x = radius;
          vx = -vx * currentSettings.restitution;
        } else if (x + radius > canvas.width) {
          x = canvas.width - radius;
          vx = -vx * currentSettings.restitution;
        }

        if (y - radius < 0) {
          y = radius;
          vy = -vy * currentSettings.restitution;
        } else if (y + radius > canvas.height) {
          y = canvas.height - radius;
          vy = -vy * currentSettings.restitution;
          vx *= 0.98;
        }

        return { ...ball, x, y, vx, vy };
      });

      for (let i = 0; i < updatedBalls.length; i++) {
        for (let j = i + 1; j < updatedBalls.length; j++) {
          const b1 = updatedBalls[i];
          const b2 = updatedBalls[j];
          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const minDist = b1.radius + b2.radius;

          if (dist < minDist) {
            const overlap = minDist - dist;
            const nx = dx / dist;
            const ny = dy / dist;

            const totalRadius = b1.radius + b2.radius;
            const ratio1 = b2.radius / totalRadius;
            const ratio2 = b1.radius / totalRadius;

            b1.x -= nx * overlap * ratio1;
            b1.y -= ny * overlap * ratio2;
            b2.x += nx * overlap * ratio2;
            b2.y += ny * overlap * ratio1;

            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const p = (nx * kx + ny * ky);

            const rest = currentSettings.restitution;
            b1.vx -= p * nx * (1 + rest) * 0.5;
            b1.vy -= p * ny * (1 + rest) * 0.5;
            b2.vx += p * nx * (1 + rest) * 0.5;
            b2.vy += p * ny * (1 + rest) * 0.5;
          }
        }
      }

      setBalls(updatedBalls);

      updatedBalls.forEach((ball) => {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
        ctx.fillStyle = ball.color;
        ctx.shadowColor = ball.color;
        ctx.shadowBlur = 10;
        ctx.fill();
        ctx.closePath();
        ctx.shadowBlur = 0;
      });

      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">物理シミュレーション</h1>
        <p className="subtitle">画面をクリックするか「ボール追加」ボタンを押してボールを配置できます。</p>
      </header>

      <div className="canvas-wrapper">
        <canvas
          ref={canvasRef}
          className="simulation-canvas"
          onClick={handleCanvasClick}
        />
      </div>

      <ControlPanel
        settings={settings}
        onUpdateSettings={setSettings}
        onReset={handleReset}
        onAddBall={handleAddBall}
        ballCount={balls.length}
      />

      <div className="stats">
        <div className="stat-item">
          <span>ボール数</span>
          <span className="stat-value">{balls.length}</span>
        </div>
        <div className="stat-item">
          <span>重力</span>
          <span className="stat-value">{settings.gravity.toFixed(1)}</span>
        </div>
        <div className="stat-item">
          <span>反発係数</span>
          <span className="stat-value">{settings.restitution.toFixed(2)}</span>
        </div>
      </div>
    </div>
  );
}
